# -*- coding: utf-8 -*-
from docx import Document
from docx.shared import Pt
from docx.oxml.ns import qn

path = r'docs\集装箱门把手智能检测与多智能体协同系统设计与实现.docx'
doc = Document(path)
for name in ['Normal','Heading 1','Heading 2','Heading 3']:
    st=doc.styles[name]; st.font.name='SimSun' if name=='Normal' else 'SimHei'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'宋体' if name=='Normal' else '黑体'); st._element.rPr.rFonts.set(qn('w:ascii'),'Arial'); st._element.rPr.rFonts.set(qn('w:hAnsi'),'Arial')

details = {
'第1章 绪论': ['本项目的工程背景来自检测现场的连续生产过程。图片由不同员工在不同时间、不同电脑上采集，文件夹既可能来自本地磁盘，也可能来自 OSS。系统必须容忍上传顺序不同、网络短暂中断和同一图片被多个员工重复提交。', '研究的关键问题可以归纳为三个层面：第一，如何把非结构化图片转化为可追踪的检测任务；第二，如何在员工共享部门资源的同时保持任务和对话隔离；第三，如何让模型结果经过人工审批后再成为企业公共事实。', '因此，本文不把智能体看作独立聊天机器人，而是把它放入检测业务的权限、事务和审计链路中。Agent 负责理解和辅助，业务 Service 负责事实和授权，主管负责质量决策。'],
'第2章 需求分析与业务规则': ['普通员工的核心路径是创建任务、上传文件夹、进行预检查、选择检测策略、等待模型完成、检查失败图片并提交主管。主管的核心路径是查看待审任务、识别重复图片、左右对比、给出审批结论并发布公共记录。', '系统把审批前和审批后数据明确分开。审批前数据保存在员工任务空间，不参与部门公共统计；审批后数据形成公共检测记录，任何员工都可以查询，但公共记录的写权限仅授予主管。', '对于本地离线重复，系统不阻止员工上传，而是在主管审核池按 SHA-256 聚合。这样既不影响员工工作连续性，也不会因为自动删除导致证据丢失。'],
'第3章 系统总体架构设计': ['请求链路采用同步和异步结合的方式。创建任务和生成预签名 URL 是同步接口；模型推理通过 Kafka 事件异步执行；进度和 Agent 回复通过查询、SSE 或 AG-UI 流式返回。', '模块边界通过 Maven 依赖和 Java 包路径体现。检测模块拥有任务和图片数据，AI 模块通过 Detection API 获取数据，Server 只做启动装配。未来将本地 Facade 替换为 HTTP 客户端时，上层业务无需改变。', '架构设计还考虑了降级：AgentScope 未配置 Key 时不创建 Agent Bean，OSS 或 Kafka 暂不可用时返回明确的业务状态，避免外部依赖故障扩散为整个系统不可启动。'],
'第4章 检测业务流程与权限模型': ['任务状态转换必须有前置条件。例如，只有 RUNNING 或 PARTIAL_FAILED 才能提交结果，只有 READY_FOR_REVIEW 才能进入主管审核，只有 APPROVED 才能发布 PUBLIC。非法转换统一返回业务错误。', '数据范围由登录用户所属部门和授权关系计算。前端传入的员工 ID、部门 ID 和任务所有者字段不能作为权限依据，服务端必须从 Authentication 和数据库授权关系重新得到。', '主管审批不是简单修改一个状态字段，而是保存审批人、审批时间、结论、说明、模型版本和结果快照，使日后可以解释为什么某批图片被发布。'],
'第5章 多用户共享数据与一致性设计': ['任务所有者模型解决员工之间的直接冲突，版本模型解决主管公共修改的并发冲突，追加记录模型解决多人复核意见的合并问题。三种策略分别对应不同的数据生命周期。', '版本冲突页面应展示服务器版本、当前编辑人和更新时间，并提供重新加载、复制差异和放弃修改选项。对于不能自动合并的图片标注，系统保留两个版本并创建重复工单。', 'Outbox 事件表还承担恢复作用。应用重启后，发布器可以继续发送未完成事件；消费者按 eventId 去重，保证重复消息不会重复生成公共记录。'],
'第6章 AgentScope 多智能体设计': ['员工助手先判断用户是在查询任务、解释图片、检索标准还是生成草稿，再选择专用 Agent。专用 Agent 返回结构化事实、引用和风险提示，编排器负责组织成自然语言。', 'Agent 工具调用采用最小权限原则。查询工具只返回当前用户可见数据，写工具需要确认令牌和版本号，主管专用工具不注册到员工 Agent 的 Toolkit 中。', '会话上下文中保存使用的 Agent ID、Skill 版本、工具调用和数据来源。这样当员工对同一任务再次提问时，可以复现当时的上下文，又不会读取其他用户的私聊。'],
'第7章 数据库与接口设计': ['图片指纹表用于快速判断文件是否已登记，检测运行表用于保存每次模型运行，公共记录表用于保存审批后的部门事实。三者不能合并为一张“大表”，否则历史版本和权限边界会混乱。', '5000 张工作单元通过主表和明细表关联，主表记录负责人、策略、进度和版本，明细表记录 imageId、文件名、对象 Key、指纹和图片状态。单张图片失败时只更新明细，不必回滚整批任务。', '接口响应采用统一 Result 包装，列表使用分页，图片访问返回短期签名 URL，错误响应使用稳定错误码，便于前端和未来微服务客户端兼容。'],
'第8章 前端交互与复查对比设计': ['预检查结果应在开始检测前明确告诉员工哪些图片会被跳过、哪些图片可重试、哪些图片正在被占用。策略选择不能隐藏在默认值中，员工必须明确确认。', '主管双面板的同步索引只负责图片位置同步，左右两侧的模型结果仍分别展示。主管可以放大查看原图和标注图，并在同一页面填写对比结论。', '签名 URL 失效、图片加载失败和左右数量不一致都要有明确的空状态或重试按钮，不能把网络错误显示成“未检测到缺陷”。'],
'第9章 部署配置与可观测性': ['环境配置按“示例可提交、真实值不提交”执行。数据库、OSS、Kafka、DashScope 和 Langfuse 的密钥通过环境变量或平台 Secret 注入，日志和异常中不得打印。', '部署时先执行数据库迁移，再启动 Server；健康检查需要区分应用进程健康、数据库连接健康和消息组件健康。检测服务不可用时，任务应停留在可恢复状态。', '统一 traceId 将员工上传、异步推理、主管审批和公共发布串成一条链路。指标除请求耗时外，还应关注审批等待时间、重复图片比例和工作单元失败率。'],
'第10章 测试方案与质量保证': ['单元测试验证状态机、指纹归一化、版本冲突和权限策略；集成测试验证 MySQL 迁移、对象存储签名和 Kafka 事件；端到端测试验证从员工上传到公共发布的完整路径。', '并发测试需要同时模拟两个员工处理不同任务、两个员工上传同一图片、两个主管审批同一工单以及网络断线重试。每种场景都要检查数据是否可恢复和审计是否完整。', 'Agent 测试不仅判断回答文本，还要断言工具是否正确、数据来源是否真实、敏感请求是否被拒绝，以及需要人工确认时是否停止自动执行。'],
'第11章 系统演进与微服务拆分': ['当前模块化单体共享进程和事务，适合单公司部署。拆分时优先考虑 GPU 推理、图片对象服务和 Agent 运行服务，因为这些能力的资源类型和扩展节奏与业务审批不同。', '服务拆分后，检测任务事件和公共契约必须版本化。消费者应兼容新增字段，破坏性变化通过新版本事件发布，并保留一段双写或双读迁移期。', '拆分的判断依据包括独立扩展需求、团队边界、故障隔离和数据合规，而不是为了追求服务数量。'],
'第12章 结论与展望': ['系统把检测结果从一次模型调用提升为完整业务事实：它包含图片、运行、模型、操作者、时间、复核和审批。该结构能够支持质量追溯、责任认定和历史比较。', '多智能体的价值不是替代主管，而是降低查询、解释、汇总和报告草稿的成本。最终质量结论仍由具备权限的人员确认，并通过审计记录形成可验证的业务过程。', '后续可基于真实数据评估模型置信度、重复检测比例、审批效率和 Agent 工具成功率，再决定是否引入长期记忆、向量检索和微服务部署。']}

for title, texts in details.items():
    doc.add_heading(title + ' 详细论述', level=2)
    for text in texts: doc.add_paragraph(text)

doc.save(path)
print(path)
